export const MIB = 1024 * 1024;
export const RESPONSE_LIMIT_BYTES = 64 * MIB;
export const MP4_PREFIX = Buffer.from("000000186674797069736f6d0000020069736f6d69736f32", "hex");
export const ASSET_RANGE_START = 32;
export const ASSET_RANGE_BYTES = 4096;
const ASSET_DOWNLOAD_CHUNK_BYTES = 256 * 1024;
type Obj = Record<string, any>;

export class HarnessFailure extends Error {}
export class PrerequisiteFailure extends Error {}

const round = (value: number, digits = 3): number => Number(value.toFixed(digits));
const percentile = (values: number[], fraction: number): number => values.length ? [...values].sort((a, b) => a - b)[Math.max(0, Math.min(values.length - 1, Math.ceil(fraction * values.length) - 1))]! : 0;

export function processMemory(pid: number): Obj {
  let status: string; try { status = readFileSync(`/proc/${pid}/status`, "utf8"); } catch { throw new HarnessFailure(`process ${pid} exited while memory was sampled`); }
  const kib = (name: string): number => Number(new RegExp(`^${name}:\\s+(\\d+)`, "mu").exec(status)?.[1] ?? 0);
  let pss = 0; try { pss = Number(/^Pss:\s+(\d+)/mu.exec(readFileSync(`/proc/${pid}/smaps_rollup`, "utf8"))?.[1] ?? 0); } catch { /* optional */ }
  return { rss_mib: kib("VmRSS") / 1024, high_water_mib: kib("VmHWM") / 1024, pss_mib: pss / 1024 };
}

export class Sampler {
  readonly samples: Obj[] = []; private timer?: NodeJS.Timeout; private started = 0; private failure?: Error; private readonly pids: Record<string, number>; private readonly intervalMs: number;
  constructor(pids: Record<string, number>, intervalMs = 50) { this.pids = pids; this.intervalMs = intervalMs; }
  start(): void { this.started = performance.now(); const sample = (): void => { try { const item: Obj = { elapsed_seconds: (performance.now() - this.started) / 1000 }; for (const [name, pid] of Object.entries(this.pids)) item[name] = processMemory(pid); this.samples.push(item); } catch (error) { this.failure = error instanceof Error ? error : new Error(String(error)); if (this.timer) clearInterval(this.timer); } }; sample(); this.timer = setInterval(sample, this.intervalMs); }
  stop(): void { if (this.timer) clearInterval(this.timer); if (this.failure) throw this.failure; }
  maxCurrentRss(name: string): number { return Math.max(0, ...this.samples.map((sample) => Number(sample[name]?.rss_mib ?? 0))); }
  lifetimeHighWaterEvidence(name: string): Obj { const start = Number(this.samples[0]?.[name]?.high_water_mib ?? 0); const end = Number(this.samples.at(-1)?.[name]?.high_water_mib ?? 0); return { start_rss_mib: round(start), end_rss_mib: round(end), growth_mib: round(Math.max(0, end - start)) }; }
}

async function withSampler<T>(pids: Record<string, number>, operation: (sampler: Sampler) => Promise<T>, intervalMs = 50): Promise<T> { const sampler = new Sampler(pids, intervalMs); sampler.start(); try { return await operation(sampler); } finally { sampler.stop(); } }
async function memorySummary(pid: number, durationMs = 1000, intervalMs = 100): Promise<Obj> { const samples: Obj[] = []; const deadline = performance.now() + durationMs; while (performance.now() < deadline) { samples.push(processMemory(pid)); await delay(intervalMs); } const rss = samples.map((item) => item.rss_mib as number); const pss = samples.map((item) => item.pss_mib as number).filter((value) => value > 0); return { rss_mib_median: round(percentile(rss, 0.5)), rss_mib_p95: round(percentile(rss, 0.95)), rss_mib_max: round(Math.max(...rss)), pss_mib_median: pss.length ? round(percentile(pss, 0.5)) : 0, lifetime_high_water_rss_mib: round(Math.max(...samples.map((item) => item.high_water_mib as number))), sample_count: samples.length }; }

export function assetGatewayRssEvidence(phasePeakRssMib: number, phaseStartRssMib: number, originalIdleRssMib: number): Obj { return { gateway_phase_delta_rss_mib: round(Math.max(0, phasePeakRssMib - phaseStartRssMib)), gateway_cumulative_delta_from_original_idle_mib: round(Math.max(0, phasePeakRssMib - originalIdleRssMib)) }; }
function rssSlope(samples: Obj[], name: string): number { if (samples.length < 3) return 0; const tail = samples.slice(Math.floor(samples.length / 3)); const xs = tail.map((sample) => Number(sample.elapsed_seconds)); const ys = tail.map((sample) => Number(sample[name].rss_mib)); const meanX = xs.reduce((a, b) => a + b, 0) / xs.length; const meanY = ys.reduce((a, b) => a + b, 0) / ys.length; const denominator = xs.reduce((sum, value) => sum + (value - meanX) ** 2, 0); return denominator ? xs.reduce((sum, x, index) => sum + (x - meanX) * (ys[index]! - meanY), 0) / denominator * 60 : 0; }

export class MockState { assets = new Map<string, number>(); imageRawBytes = 11 * MIB; imageItemCount = 10; standardImageRequests = 0; responsesToolImageRequests = 0; activeStreams = 0; peakStreams = 0; begin(): void { this.activeStreams += 1; this.peakStreams = Math.max(this.peakStreams, this.activeStreams); } end(): void { this.activeStreams -= 1; } resetStreamPeak(): void { if (this.activeStreams) throw new HarnessFailure("cannot reset mock concurrency while a stream is active"); this.peakStreams = 0; } }

async function requestJson(request: IncomingMessage): Promise<Obj> { const chunks: Buffer[] = []; for await (const chunk of request) chunks.push(Buffer.from(chunk)); const value = JSON.parse(Buffer.concat(chunks).toString("utf8") || "{}"); if (typeof value !== "object" || value === null || Array.isArray(value)) throw new Error("body is not an object"); return value as Obj; }
function jsonResponse(response: ServerResponse, status: number, value: unknown): void { const body = Buffer.from(JSON.stringify(value)); response.writeHead(status, { "content-type": "application/json", "content-length": body.length }); response.end(body); }
async function streamBytes(response: ServerResponse, state: MockState, total: number, chunkSize: number, delayMs: number, contentType = "application/octet-stream", prefix = Buffer.alloc(0)): Promise<void> {
  state.begin();
  try {
    response.writeHead(200, { "content-type": contentType, "content-length": total });
    let remaining = total;
    if (prefix.length) { response.write(prefix); remaining -= prefix.length; }
    const block = Buffer.alloc(Math.min(chunkSize, remaining), "x");
    while (remaining > 0 && !response.destroyed) {
      const take = Math.min(block.length, remaining);
      if (!response.write(block.subarray(0, take))) {
        await new Promise<void>((done) => {
          const drained = (): void => { response.off("close", closed); done(); };
          const closed = (): void => { response.off("drain", drained); done(); };
          response.once("drain", drained);
          response.once("close", closed);
        });
      }
      remaining -= take;
      if (delayMs) await delay(delayMs);
    }
    if (!response.destroyed) response.end();
  } finally { state.end(); }
}

export function createMockServer(state = new MockState()): Server {
  return createServer(async (request, response) => { try {
    const path = request.url ?? "/";
    if (request.method === "POST" && path === "/v1/chat/completions") { const body = await requestJson(request); const benchmark = body.benchmark; if (benchmark?.mode === "stream" || benchmark?.mode === "oversize") { await streamBytes(response, state, Number(benchmark.bytes), Math.max(4096, Math.min(Number(benchmark.chunk_bytes ?? 262144), MIB)), Number(benchmark.delay_ms ?? 0), "text/event-stream"); return; } jsonResponse(response, 200, { id: "chatcmpl-memory-benchmark", object: "chat.completion", model: body.model ?? "benchmark-text", choices: [{ index: 0, message: { role: "assistant", content: "ok" }, finish_reason: "stop" }], usage: { prompt_tokens: 2, completion_tokens: 1, total_tokens: 3 } }); return; }
    if (request.method === "POST" && path === "/api/v3/contents/generations/tasks") { const body = await requestJson(request); const assetMib = Number(body.benchmark_asset_mib ?? 100); const id = `bench-${assetMib}-${randomUUID().slice(0, 12)}`; state.assets.set(id, assetMib * MIB); jsonResponse(response, 200, { id }); return; }
    if (request.method === "POST" && path === "/v1/images/generations") { const body = await requestJson(request); if (body.n !== state.imageItemCount) { jsonResponse(response, 400, { error: "unexpected image result count" }); return; } state.standardImageRequests += 1; const base = Math.floor(state.imageRawBytes / state.imageItemCount); const remainder = state.imageRawBytes % state.imageItemCount; const data = Array.from({ length: state.imageItemCount }, (_, index) => ({ b64_json: Buffer.alloc(base + (index < remainder ? 1 : 0), "x").toString("base64"), revised_prompt: `memory benchmark image ${index}` })); jsonResponse(response, 200, { created: 1_700_000_000, data, usage: { input_tokens: 1, output_tokens: 1, total_tokens: 2 }, provider_secret: "must-not-reach-the-client" }); return; }
    if (request.method === "POST" && path === "/v1/responses") { const body = await requestJson(request); if (body.stream !== false || body.tools?.[0]?.type !== "image_generation") { jsonResponse(response, 400, { error: "unexpected Responses image request" }); return; } state.responsesToolImageRequests += 1; jsonResponse(response, 200, { id: "resp_memory_image", output: [{ type: "image_generation_call", id: "ig_memory_image", result: Buffer.alloc(state.imageRawBytes, "x").toString("base64"), provider_secret: "must-not-reach-the-client" }], usage: { input_tokens: 1, output_tokens: 1, total_tokens: 2 } }); return; }
    const task = /^\/api\/v3\/contents\/generations\/tasks\/(.+)$/u.exec(path); if (request.method === "GET" && task) { const bytes = state.assets.get(task[1]!); if (bytes === undefined) { jsonResponse(response, 404, { error: "unknown job" }); return; } jsonResponse(response, 200, { id: task[1], status: "succeeded", duration: 1, content: { video_url: `http://${request.headers.host}/assets/${task[1]}` } }); return; }
    const asset = /^\/assets\/(.+)$/u.exec(path); if (request.method === "GET" && asset) { const bytes = state.assets.get(asset[1]!); if (bytes === undefined) { jsonResponse(response, 404, { error: "unknown asset" }); return; } await streamBytes(response, state, bytes, 256 * 1024, 0.25, "video/mp4", MP4_PREFIX); return; }
    jsonResponse(response, 404, { error: "mock route not found" });
  } catch { jsonResponse(response, 400, { error: "invalid request" }); } });
}

interface ApiResponse { status: number; body: Buffer; headers: Record<string, string> }
function requestForURL(target: URL, options: RequestOptions, callback: (response: IncomingMessage) => void) { if (target.protocol === "http:") return httpRequest(target, options, callback); if (target.protocol === "https:") return httpsRequest(target, options, callback); throw new HarnessFailure(`unsupported benchmark URL protocol: ${target.protocol}`); }
function responseHeaders(response: IncomingMessage): Record<string, string> { const headers: Record<string, string> = {}; for (const [name, value] of Object.entries(response.headers)) if (value !== undefined) headers[name] = Array.isArray(value) ? value.join(", ") : value; return headers; }
export async function apiRequest(baseUrl: string, method: string, path: string, token: string, payload?: unknown, timeoutMs = 30_000, extraHeaders: Record<string, string> = {}): Promise<ApiResponse> {
  const target = new URL(path, baseUrl); const headers: Record<string, string | number> = { authorization: `Bearer ${token}`, connection: "close", ...extraHeaders }; const body = payload === undefined ? undefined : Buffer.from(JSON.stringify(payload)); if (body) { headers["content-type"] = "application/json"; headers["content-length"] = body.length; }
  return await new Promise<ApiResponse>((resolveResponse, rejectResponse) => { const chunks: Buffer[] = []; let received = 0; let settled = false; const reject = (error: Error): void => { if (!settled) { settled = true; rejectResponse(error); } }; const request = requestForURL(target, { method, headers }, (response) => { const declared = Number(response.headers["content-length"] ?? 0); if (Number.isFinite(declared) && declared > 80 * MIB) { response.destroy(new HarnessFailure("buffered benchmark response exceeds 80 MiB")); return; } response.on("data", (raw: Buffer) => { const chunk = Buffer.from(raw); received += chunk.length; if (received > 80 * MIB) { response.destroy(new HarnessFailure("buffered benchmark response exceeds 80 MiB")); return; } chunks.push(chunk); }); response.once("aborted", () => reject(new HarnessFailure("buffered benchmark response was aborted"))); response.once("error", reject); response.once("end", () => { if (settled) return; settled = true; resolveResponse({ status: response.statusCode ?? 0, body: Buffer.concat(chunks, received), headers: responseHeaders(response) }); }); }); request.setTimeout(timeoutMs, () => request.destroy(new HarnessFailure(`${method} ${target.pathname} timed out after ${timeoutMs} ms`))); request.once("error", reject); request.end(body); });
}
export async function apiJson(baseUrl: string, method: string, path: string, token: string, payload?: unknown, expected = [200, 201, 202], timeoutMs = 30_000): Promise<Obj> { const response = await apiRequest(baseUrl, method, path, token, payload, timeoutMs); if (!expected.includes(response.status)) throw new HarnessFailure(`${method} ${path} returned HTTP ${response.status}: ${response.body.subarray(0, 1000).toString("utf8")}`); try { return JSON.parse(response.body.toString("utf8")) as Obj; } catch { throw new HarnessFailure(`${method} ${path} returned non-JSON success`); } }

export function customModelRoutePayload(tenant: string, publicModel: string, upstreamAccountId: string, upstreamModel: string, protocol: string): Obj { return { tenant_external_id: tenant, public_model: publicModel, upstream_account_id: upstreamAccountId, upstream_model: upstreamModel, protocol, priority: 0, custom_model_confirmed: true }; }
export async function seed(controlUrl: string, gatewayUrl: string, serviceToken: string, mockUrl: string, requestJson = apiJson, proveChat = smallChat): Promise<string> {
  const tenant = "memory-benchmark";
  const upstream = async (name: string, driver: string): Promise<string> => String((await requestJson(controlUrl, "POST", "/internal/v1/upstreams", serviceToken, { tenant_external_id: tenant, name, driver, config: { base_url: mockUrl }, credential: { type: "none" } })).id);
  const textUpstream = await upstream("Memory benchmark text", "http-json"); const textRoute = await requestJson(controlUrl, "POST", "/internal/v1/model-routes", serviceToken, customModelRoutePayload(tenant, "benchmark-text", textUpstream, "benchmark-text", "openai")); await requestJson(controlUrl, "POST", "/internal/v1/prices/USD/benchmark-text", serviceToken, { input_per_million: "0.01", output_per_million: "0.02" });
  const assetUpstream = await upstream("Memory benchmark asset", "volcengine-seedance"); const assetRoute = await requestJson(controlUrl, "POST", "/internal/v1/model-routes", serviceToken, customModelRoutePayload(tenant, "benchmark-seedance", assetUpstream, "benchmark-seedance", "generation")); await requestJson(controlUrl, "POST", "/internal/v1/generation-prices/USD/benchmark-seedance", serviceToken, { billing_unit: "second", price_per_unit: "0.01" });
  const imageUpstream = await upstream("Memory benchmark image", "http-json"); const imageRoute = await requestJson(controlUrl, "POST", "/internal/v1/model-routes", serviceToken, customModelRoutePayload(tenant, "benchmark-image", imageUpstream, "benchmark-image-upstream", "generation")); await requestJson(controlUrl, "POST", "/internal/v1/generation-prices/USD/benchmark-image", serviceToken, { billing_unit: "image", price_per_unit: "0.01" });
  const responsesImageUpstream = String((await requestJson(controlUrl, "POST", "/internal/v1/upstreams", serviceToken, { tenant_external_id: tenant, name: "Memory benchmark Responses-tool image", driver: "http-json", config: { base_url: mockUrl, image_api_mode: "responses-tool", image_main_model: "gpt-5.6-sol" }, credential: { type: "none" } })).id); const responsesImageRoute = await requestJson(controlUrl, "POST", "/internal/v1/model-routes", serviceToken, customModelRoutePayload(tenant, "benchmark-responses-image", responsesImageUpstream, "gpt-image-2", "generation")); await requestJson(controlUrl, "POST", "/internal/v1/generation-prices/USD/benchmark-responses-image", serviceToken, { billing_unit: "image", price_per_unit: "0.01" });
  const issued = await requestJson(controlUrl, "POST", "/internal/v1/keys", serviceToken, { tenant_external_id: tenant, principal_external_id: "memory-benchmark-user", alias: "Memory benchmark credential", currency: "USD", initial_balance: "100000", route_ids: [textRoute.id, assetRoute.id, imageRoute.id, responsesImageRoute.id], policy: { requests_per_minute: 1_000_000, tokens_per_minute: 1_000_000_000, max_concurrency: 32, daily_budget: null, weekly_budget: null, lifetime_budget: null } }); const key = String(issued.key); await proveChat(gatewayUrl, key); return key;
}

export function chatPayload(mode = "small", bytes = 0, delayMs = 0): Obj { const payload: Obj = { model: "benchmark-text", messages: [{ role: "user", content: "memory benchmark" }], max_tokens: 1 }; if (mode !== "small") payload.benchmark = { mode, bytes, chunk_bytes: 256 * 1024, delay_ms: delayMs }; return payload; }
export async function smallChat(url: string, key: string): Promise<number> {
  const target = new URL("/v1/chat/completions", url); const body = Buffer.from(JSON.stringify(chatPayload()));
  const response = await new Promise<ApiResponse>((resolveResponse, rejectResponse) => {
    const chunks: Buffer[] = []; let received = 0; let settled = false;
    const settleError = (error: Error): void => { if (!settled) { settled = true; rejectResponse(error); } };
    const request = httpRequest({ hostname: target.hostname, port: target.port, path: `${target.pathname}${target.search}`, method: "POST", headers: { authorization: `Bearer ${key}`, "content-type": "application/json", "content-length": body.length, connection: "close" } }, (incoming) => {
      incoming.on("data", (chunk: Buffer) => { received += chunk.length; if (received > MIB) { incoming.destroy(new HarnessFailure("small chat exceeded the 1 MiB diagnostic response limit")); return; } chunks.push(chunk); });
      incoming.once("error", settleError);
      incoming.once("end", () => { if (settled) return; settled = true; const headers: Record<string, string> = {}; for (const [name, value] of Object.entries(incoming.headers)) if (value !== undefined) headers[name] = Array.isArray(value) ? value.join(", ") : value; resolveResponse({ status: incoming.statusCode ?? 0, body: Buffer.concat(chunks, received), headers }); });
    });
    request.setTimeout(30_000, () => request.destroy(new HarnessFailure("small chat timed out after 30000 ms")));
    request.once("error", settleError); request.end(body);
  });
  if (response.status !== 200 || !response.body.length) { const detail = response.body.subarray(0, 512).toString("utf8").replaceAll(/[\r\n\t]+/g, " ").trim(); throw new HarnessFailure(`small chat failed with HTTP ${response.status}${detail ? `: ${detail}` : ""}`); } return response.body.length;
}
export async function streamChat(url: string, key: string, bytes: number, delayMs = 0): Promise<number> {
  const target = new URL("/v1/chat/completions", url); const body = Buffer.from(JSON.stringify(chatPayload("stream", bytes, delayMs)));
  return await new Promise<number>((resolveResponse, rejectResponse) => { let received = 0; let settled = false; const reject = (error: Error): void => { if (!settled) { settled = true; rejectResponse(error); } }; const request = requestForURL(target, { method: "POST", headers: { authorization: `Bearer ${key}`, "content-type": "application/json", "content-length": body.length, connection: "close" } }, (response) => { response.on("data", (raw: Buffer) => { received += Buffer.byteLength(raw); }); response.once("aborted", () => reject(new HarnessFailure("stream response was aborted"))); response.once("error", reject); response.once("end", () => { if (settled) return; settled = true; const status = response.statusCode ?? 0; if (status !== 200 || received !== bytes) { rejectResponse(new HarnessFailure(`stream returned HTTP ${status} and ${received} bytes; expected ${bytes}`)); return; } resolveResponse(received); }); }); request.setTimeout(180_000, () => request.destroy(new HarnessFailure("stream chat timed out after 180000 ms"))); request.once("error", reject); request.end(body); });
}

function scaleUuid(namespace: number, sequence: number): string { const hex = (BigInt(namespace) << 112n | BigInt(sequence)).toString(16).padStart(32, "0"); return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`; }
function seedControlScale(databasePath: string, rowCount = 100_000): void {
  const database = new DatabaseSync(databasePath, { timeout: 60_000 }); database.exec("PRAGMA busy_timeout = 60000"); const tenantId = String((database.prepare("SELECT id FROM tenants WHERE external_id = ?").get("memory-benchmark") as Obj).id);
  const tenants = database.prepare("INSERT INTO tenants (id, external_id, created_at) VALUES (?, ?, ?)");
  const upstreams = database.prepare("INSERT INTO upstream_accounts (id, tenant_id, name, driver, auth_kind, config_json, status, credential_generation, created_at, updated_at) VALUES (?, ?, ?, 'http-json', 'none', '{}', 'active', 1, ?, ?)");
  const routes = database.prepare("INSERT INTO model_routes (id, tenant_id, public_model, upstream_account_id, upstream_model, protocol, priority, enabled, created_at, updated_at) VALUES (?, ?, ?, ?, ?, 'openai', 0, 1, ?, ?)");
  const principals = database.prepare("INSERT INTO service_principals (id, name, status, credential_generation, created_at, updated_at) VALUES (?, ?, 'active', 1, ?, ?)");
  const credentials = database.prepare("INSERT INTO service_credentials (id, service_principal_id, generation, secret_hash, fingerprint, scopes_json, tenant_external_id, created_at, revoked_at) VALUES (?, ?, 1, ?, ?, '[\"requests:read\"]', NULL, ?, NULL)");
  database.exec("BEGIN IMMEDIATE"); try { for (let index = 1; index <= rowCount; index += 1) { const suffix = String(index).padStart(6, "0"); tenants.run(scaleUuid(5, index), `scale-tenant-${suffix}`, index); upstreams.run(scaleUuid(6, index), tenantId, `scale-upstream-${suffix}`, index, index); routes.run(scaleUuid(7, index), tenantId, `scale-model-${suffix}`, scaleUuid(6, index), `scale-model-${suffix}`, index, index); principals.run(scaleUuid(8, index), `scale-service-${suffix}`, index, index); credentials.run(scaleUuid(9, index), scaleUuid(8, index), Buffer.from("scale-fixture-hash"), `scale-fingerprint-${suffix}`, index); } database.exec("COMMIT"); } catch (error) { database.exec("ROLLBACK"); throw error; }
  for (const table of ["tenants", "upstream_accounts", "model_routes", "service_principals"]) database.exec(`ANALYZE ${table}`); database.close();
}

async function runControlScale(controlUrl: string, token: string, pid: number, idle: number): Promise<Obj> { const paths = ["/internal/v1/tenants?limit=1000000", "/internal/v1/service-tokens?limit=1000000", "/internal/v1/upstreams?limit=1000000", "/internal/v1/model-routes?limit=1000000"]; const started = performance.now(); return withSampler({ control: pid }, async (sampler) => { const pages = await Promise.all([...paths, ...paths, ...paths, ...paths].map(async (path) => { const before = performance.now(); const response = await apiRequest(controlUrl, "GET", path, token, undefined, 60_000); let rows: unknown; try { rows = JSON.parse(response.body.toString("utf8")); } catch { throw new HarnessFailure(`control scale path returned invalid JSON: ${path}`); } if (response.status !== 200 || !Array.isArray(rows)) throw new HarnessFailure(`control scale path failed with HTTP ${response.status}: ${path}`); return { path, status: response.status, rows: rows.length, response_bytes: response.body.length, latency_ms: round(performance.now() - before) }; })); const peak = sampler.maxCurrentRss("control"); return { fixture_rows_per_resource: 100_000, concurrency: 16, pages, maximum_page_rows: Math.max(...pages.map((page) => page.rows)), maximum_response_bytes: Math.max(...pages.map((page) => page.response_bytes)), maximum_latency_ms: Math.max(...pages.map((page) => page.latency_ms)), duration_seconds: round((performance.now() - started) / 1000), control_peak_rss_mib: round(peak), control_delta_rss_mib: round(peak - idle), sample_count: sampler.samples.length }; }); }

interface ImageBenchmarkMode { name: "standard-openai-images" | "codex-responses-tool"; model: string; results: number; upstreamRequests: () => number }
