function freePort(): Promise<number> { return new Promise((done, reject) => { const server = createServer(); server.once("error", reject); server.listen(0, "127.0.0.1", () => { const address = server.address(); if (!address || typeof address === "string") { reject(new Error("failed to allocate port")); return; } const port = address.port; server.close((error) => error ? reject(error) : done(port)); }); }); }
