interface Arguments { profile: "short" | "acceptance"; binary?: string; output?: string; assetMib?: number; soakSeconds?: number; concurrency?: number; streamMib?: number; targetRps: number; idleMaxMib: number; streamDeltaMaxMib: number; controlListDeltaMaxMib: number; imageDeltaMaxMib: number; assetGatewayDeltaMaxMib: number; assetWorkerDeltaMaxMib: number; retainedDeltaMaxMib: number; soakSlopeMaxMibPerMinute: number; gatewayLimitMib: number; gatewayHeadroomMib: number; comparisonRssMib: number; comparisonMaxRatio: number }
const argumentKeys: Record<string, keyof Arguments> = { "--binary": "binary", "--output": "output", "--asset-mib": "assetMib", "--soak-seconds": "soakSeconds", "--concurrency": "concurrency", "--stream-mib": "streamMib", "--target-rps": "targetRps", "--idle-max-mib": "idleMaxMib", "--stream-delta-max-mib": "streamDeltaMaxMib", "--control-list-delta-max-mib": "controlListDeltaMaxMib", "--image-delta-max-mib": "imageDeltaMaxMib", "--asset-gateway-delta-max-mib": "assetGatewayDeltaMaxMib", "--asset-worker-delta-max-mib": "assetWorkerDeltaMaxMib", "--retained-delta-max-mib": "retainedDeltaMaxMib", "--soak-slope-max-mib-per-minute": "soakSlopeMaxMibPerMinute", "--gateway-limit-mib": "gatewayLimitMib", "--gateway-headroom-mib": "gatewayHeadroomMib", "--comparison-rss-mib": "comparisonRssMib", "--comparison-max-ratio": "comparisonMaxRatio" };
